y=inb.astype(float)
def fit(F,y,w8=20.):
    F=torch.tensor(F,dtype=torch.float32); Y=torch.tensor(y,dtype=torch.float32)
    w=torch.zeros(F.shape[1],requires_grad=True); b=torch.zeros(1,requires_grad=True)
    opt=torch.optim.Adam([w,b],lr=0.05)
    for _ in range(1500):
        z=F@w+b; l=torch.nn.functional.binary_cross_entropy_with_logits(z,Y,pos_weight=torch.tensor(w8)); opt.zero_grad(); l.backward(); opt.step()
    return w.detach().numpy(), b.item()
for k in [6,8,10,12,14]:
    t=1-k/20
    F=np.c_[S[k], np.full(len(a),t), c]
    w,b=fit(F,y)
    z=F@w+b
    for thr in [0,1,2]:
