import numpy as np, torch, model
net=model.load()
c=np.load('pool_c2.npy'); xi=np.load('pool_xi2.npy'); a0=np.load('a_pool2.npy')
def bad(a):
    m=np.zeros(len(a),bool)
    for i in [0,2,3,10]: m|=np.asarray(model.in_basin(i,a))
    return m
b0=bad(a0)
ref=a0[~b0]; cref=c[~b0]
def typical(a,cc):
    d=np.sqrt(((a[:,None,:]-ref[None])**2).sum(-1)+ (3*(cc[:,None]-cref[None]))**2)
    return d.min(1)<0.3
def run(w,b,thr,lo,hi,push):
    x=torch.tensor(xi); C=torch.tensor(c)
    with torch.no_grad():
        for k in range(20):
            t=torch.full((len(x),),1-k/20)
            v=net.velocity(x,t,C,count=False)[0]
            if lo<=k<hi:
                z=x[:,0]*w[0]+x[:,1]*w[1]+t*w[2]+C*w[3]+b
                f=(z>thr).float()[:,None]
                v=v+f*torch.tensor(push,dtype=torch.float32)[None]
            x=x-v/20
    return x.numpy()
